function IconButton({icon:Icon,label,...props}:{icon:IconComponent;label:string}&React.ButtonHTMLAttributes<HTMLButtonElement>) { return <Button size="icon" variant="ghost" aria-label={label} title={label} {...props}><Icon size={16}/></Button>; }
function ImagePreview({src,alt,className}:{src:string;alt:string;className?:string}) {
  const [open,setOpen]=useState(false);
  const [view,setView]=useState({scale:1,x:0,y:0});const viewport=useRef<HTMLDivElement>(null),drag=useRef<{id:number;x:number;y:number}>();
  const reset=()=>setView({scale:1,x:0,y:0});
  const toggle=(value:boolean)=>{setOpen(value);reset();drag.current=undefined;};
  const zoom=(factor:number,x=0,y=0)=>setView(current=>{const scale=Math.max(.25,Math.min(8,current.scale*factor)),ratio=scale/current.scale;return {scale,x:x-(x-current.x)*ratio,y:y-(y-current.y)*ratio};});
  useEffect(()=>{
    const element=viewport.current;if(!open||!element)return;
    const wheel=(event:WheelEvent)=>{event.preventDefault();const rect=element.getBoundingClientRect(),delta=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?rect.height:1);zoom(Math.exp(-delta*.0015),event.clientX-rect.left-rect.width/2,event.clientY-rect.top-rect.height/2);};
    element.addEventListener("wheel",wheel,{passive:false});return()=>element.removeEventListener("wheel",wheel);
  },[open]);
  return <><button type="button" className={css["image-preview-trigger"]} aria-label={`放大查看：${alt}`} onClick={()=>toggle(true)}><img src={src} alt={alt} className={className}/></button><Dialog open={open} onOpenChange={toggle}><DialogContent className={css["image-preview-dialog"]}><DialogTitle className={css["sr-only"]}>图片预览</DialogTitle><DialogDescription className={css["sr-only"]}>{alt}。滚轮缩放，拖拽移动；方向键移动，+ / - 缩放，0 重置。</DialogDescription>
    <div className={css["image-viewport"]} ref={viewport} role="region" aria-label="图片查看区域" tabIndex={0}
      onPointerDown={event=>{if(event.button!==0||!event.isPrimary)return;event.preventDefault();event.currentTarget.focus({preventScroll:true});event.currentTarget.setPointerCapture(event.pointerId);drag.current={id:event.pointerId,x:event.clientX,y:event.clientY};}}
      onPointerMove={event=>{const previous=drag.current;if(!previous||previous.id!==event.pointerId)return;const x=event.clientX-previous.x,y=event.clientY-previous.y;drag.current={id:event.pointerId,x:event.clientX,y:event.clientY};setView(current=>({...current,x:current.x+x,y:current.y+y}));}}
      onPointerUp={()=>{drag.current=undefined;}} onPointerCancel={()=>{drag.current=undefined;}} onLostPointerCapture={()=>{drag.current=undefined;}}
      onKeyDown={event=>{if(["+","=","-","0"].includes(event.key)){event.preventDefault();if(event.key==="0")reset();else zoom(event.key==="-"?1/1.2:1.2);}else if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(event.key)){event.preventDefault();setView(current=>({...current,x:current.x+(event.key==="ArrowLeft"?-40:event.key==="ArrowRight"?40:0),y:current.y+(event.key==="ArrowUp"?-40:event.key==="ArrowDown"?40:0)}));}}}>
      <img src={src} alt={alt} draggable={false} style={{transform:`translate(${view.x}px,${view.y}px) scale(${view.scale})`}}/>
    </div><div className={css["image-preview-controls"]}><span>滚轮缩放 · 拖拽移动</span><Button variant="outline" size="sm" aria-label="缩小图片" disabled={view.scale<=.25} onClick={()=>zoom(1/1.2)}>−</Button><span aria-label="图片缩放比例">{Math.round(view.scale*100)}%</span><Button variant="outline" size="sm" aria-label="放大图片" disabled={view.scale>=8} onClick={()=>zoom(1.2)}>+</Button><Button variant="outline" size="sm" onClick={reset}>重置图片</Button></div>
  </DialogContent></Dialog></>;
}
function ResizeHandle({label,value,min,max,direction=1,onChange,className=""}:{label:string;value:number;min:number;max:number;direction?:number;onChange:(value:number)=>void;className?:string}) {
  const drag=useRef<{x:number;width:number}>();
  const change=(width:number)=>onChange(Math.round(Math.max(min,Math.min(max,width))));
  const end=()=>{drag.current=undefined;};
  return <div className={classes(`panel-separator ${className}`)} role="separator" tabIndex={0} aria-label={label} aria-orientation="vertical" aria-valuenow={value} aria-valuemin={min} aria-valuemax={max}
    onPointerDown={e=>{if(e.button!==0)return;e.preventDefault();e.currentTarget.focus();drag.current={x:e.clientX,width:value};e.currentTarget.setPointerCapture(e.pointerId);}}
    onPointerMove={e=>{if(drag.current)change(drag.current.width+direction*(e.clientX-drag.current.x));}}
    onPointerUp={end} onPointerCancel={end} onLostPointerCapture={end}
    onKeyDown={e=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(e.key))return;e.preventDefault();change(e.key==="Home"?min:e.key==="End"?max:value+(e.key==="ArrowRight"?20:-20)*direction);}}/>;
}
function Empty({ icon: Icon, title, children }: { icon: IconComponent; title: string; children?: ReactNode }) { return <div className={classes("empty-state")}><Icon size={30} strokeWidth={1.3} /><h3>{title}</h3>{children && <div>{children}</div>}</div>; }
function Markdown({text,base}:{text:string;base?:string}) {
  const state=useApp.getState(),record=state.state?.sessions.find(r=>r.id===state.activeId),workspace=state.state?.workspaces.find(w=>w.id===(record?.workspaceId||state.workspaceId));
  const folder=base||record?.cwd||workspace?.path||"/";
  const click=(e:React.MouseEvent<HTMLDivElement>)=>{if(e.button>1)return;const anchor=(e.target as Element).closest<HTMLAnchorElement>("a");if(!anchor)return;const path=anchor.dataset.filePath,href=anchor.getAttribute("href")||"";if(!path&&href.startsWith("#"))return;e.preventDefault();if(path){window.dispatchEvent(new CustomEvent("pi-request-files",{detail:{path}}));return;}if(anchor.getAttribute("aria-busy")==="true")return;const target=resolveLink(href,folder);if(target?.kind==="web"){anchor.setAttribute("aria-busy","true");void api("/open-url",{url:target.url}).catch(useApp.getState().fail).finally(()=>anchor.removeAttribute("aria-busy"));}};
  return <div className={classes("markdown")} onClick={click} onAuxClick={click} dangerouslySetInnerHTML={{__html:renderMarkdown(text,folder)}}/>;
}

function classes(value: string) { return value.split(/\s+/).map(name=>css[name] || name).join(" "); }
const relativeTime=(value:string)=>{const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(value))/60000));return minutes<1?"刚刚":minutes<60?`${minutes}分钟`:minutes<1440?`${Math.floor(minutes/60)}小时`:new Date(value).toLocaleDateString("zh-CN",{month:"numeric",day:"numeric"});};
function AgentModeMenu({mode,onChange,disabled=false,label="Agent 模式"}:{mode:Mode;onChange:(value:Mode)=>void;disabled?:boolean;label?:string}) {
  return <Menu label={label} buttonProps={{disabled,title:disabled?"等待当前运行结束后切换模式":undefined}} trigger={<>{mode==="minimal"?<Zap size={15}/>:<Sparkles size={15}/>}<span>{mode==="minimal"?"极简模式":"标准模式"}</span><ChevronDown size={12}/></>}><MenuItem selected={mode==="standard"} onClick={()=>{if(mode!=="standard")onChange("standard");}}>标准模式</MenuItem><MenuItem selected={mode==="minimal"} onClick={()=>{if(mode!=="minimal")onChange("minimal");}}>极简模式 · 仅四工具</MenuItem></Menu>;
}
