  const update=(data:Partial<ScheduledTask>)=>setEditing(current=>({...current,...data}));
  const mutate=async(action:()=>Promise<unknown>)=>{setPending(true);setError("");try{await action();}catch(e){setError((e as Error).message);}finally{setPending(false);}};
  const save=()=>mutate(async()=>{await api(editing?.id?`/schedules/${editing.id}`:"/schedules",editing,editing?.id?"PATCH":"POST");setEditing(undefined);});
