    const p=editor.provider,m=editor.model;const provider={...object(editor.providerJSON,"提供商高级配置"),id:p.id.trim(),...(p.baseUrl?.trim()?{baseUrl:p.baseUrl.trim()}:{}),...(p.api?{api:p.api}:{}),...(editor.key.trim()?{apiKey:editor.key.trim()}:{})};
