  useEffect(()=>{const detail=pageRef.current?.querySelector<HTMLElement>('[aria-label="MCP 详情"]');detail?.scrollIntoView({block:"nearest"});detail?.focus({preventScroll:true});},[Boolean(editor),editor?.original,editor?.scope]);
  useEffect(()=>{if(result){resultRef.current?.scrollIntoView({block:"start"});resultRef.current?.focus({preventScroll:true});}},[result]);
